\version "2.27.2"
% automatically converted by musicxml2ly from 11f-TimeSignatures-SymbolMeaning.xml
\pointAndClickOff

\header {
  texidoc = "Semantically invalid use cases for the ‘symbol’ attribute of
    <time>. The actual display is application-dependent.

    This test shows a 3/8 time signature with ‘symbol=\"cut\"’ and a complex
    1/8+2/4 time signature with ‘symbol=\"single-number\"’."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative b' {
  \clef "treble" \time 3/8 \key c \major b4. | % 2
  \once \override Staff.TimeSignature.style = #'single-number \time #'((1 . 8) (2 . 4))
  b8 b2 \bar "|."
}


% The score definition
\score {
  <<
    \new Staff = "P1" <<
      \context Staff <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \PartPOneVoiceOne
        }
      >>
    >>
  >>
  \layout {}
